/** 가이드 원발행일 조회 (없으면 undefined — 초기 기반 가이드). */
export function getGuidePublishedAt(slug: string): string | undefined {
  return GUIDE_PUBLISHED_AT[slug];
}

export function getGuideBySlug(slug: string): GuideDef | null {
  return GUIDES.find(g => g.slug === slug) || null;
}

/**
 * 가이드 토픽 클러스터 (SSoT) — 허브(/guide) 그룹핑 + 가이드 상호 내부링크(관련 가이드)에 공용.
 *   - 같은 클러스터 = 같은 검색 의도/주제 묶음 → 토픽 권위 신호 + hub-and-spoke 내부링크.
 *   - 신규 가이드 추가 시 해당 slug 를 알맞은 클러스터에 넣기만 하면 허브·관련링크 자동 반영.
 *   - 어느 클러스터에도 없는 slug 는 getGuideClusters() 가 '기타' 묶음으로 자동 포함(누락 방지).
 */
